-- Disposable database assertions; all test mutations are rolled back.
begin;
create function pg_temp.assert_true(p boolean,m text) returns void language plpgsql as $$ begin if p is distinct from true then raise exception 'Assertion failed: %',m; end if; end $$;
create function pg_temp.expect_error(statement text,expected text) returns void language plpgsql as $$ declare message text; begin begin execute statement; exception when others then message:=sqlerrm; end; if message is null or position(expected in message)=0 then raise exception 'Expected %, got %',expected,message; end if; end $$;
select set_config('request.jwt.claim.sub','11111111-1111-1111-1111-111111111111',true);
select set_config('app.application_id','',true);
select pg_temp.assert_true((select count(*)=1 from public.candidate_applications where candidate_id='TEST-C1'),'legacy application backfill');
select pg_temp.assert_true((select count(*)=1 from public.recruitment_logs where candidate_id='TEST-C1' and application_id is not null and entry_assignment_id is not null),'legacy log IDs preserved');
create temp table test_results(kind text,id text,application_id uuid);
insert into test_results select 'pool',r->>'id',null from (select public.app_upsert_candidate_profile_v1('{"name":"Pool person","home_site":"TEST","phone_no":"0823456789","channel":"LinkedIn","first_contact_date":"2026-10-10","note":"Potential engineer"}') r) x;
select pg_temp.assert_true(not exists(select 1 from public.recruitment_logs l join test_results t on t.id=l.candidate_id where t.kind='pool'),'pool has no stage');
select pg_temp.assert_true((select home_site='TEST' and group_id is null from public.candidates where candidate_id=(select id from test_results where kind='pool')),'independent profile');
insert into test_results select 'app1',r->>'candidate_id',(r->>'application_id')::uuid from (select public.app_create_candidate_application_v1(jsonb_build_object('candidate_id',(select id from test_results where kind='pool'),'group_id','TEST-G1')) r) x;
select set_config('app.application_id','',true);
insert into test_results select 'app2',r->>'candidate_id',(r->>'application_id')::uuid from (select public.app_create_candidate_application_v1(jsonb_build_object('candidate_id',(select id from test_results where kind='pool'),'group_id','TEST-G2')) r) x;
select pg_temp.assert_true((select count(*)=2 from public.recruitment_logs l join test_results t on t.application_id=l.application_id where t.kind in ('app1','app2') and result is null),'parallel pending stages are independent');
select pg_temp.expect_error(format('select public.app_create_candidate_application_v1(%L::jsonb)',jsonb_build_object('candidate_id',(select id from test_results where kind='pool'),'group_id','TEST-G2')),'APPLICATION_ALREADY_ACTIVE');
select set_config('app.application_id','',true);
select pg_temp.expect_error(format('select public.app_start_pipeline_stage_v2(%L::jsonb)',jsonb_build_object('candidate_id',(select id from test_results where kind='pool'),'pending',jsonb_build_object('opened_date','2026-10-10'))),'APPLICATION_SELECTION_REQUIRED');
create temp table original_stage as select log_id,stage_instance_id,application_id,entry_assignment_id from public.recruitment_logs where candidate_id='TEST-C1';
select public.app_transfer_candidate_application_v1(jsonb_build_object('candidate_id','TEST-C1','application_id',(select application_id from original_stage),'group_id','TEST-G2','expected_version',1,'reason','Better position fit'));
select pg_temp.assert_true((select count(*)=1 from public.recruitment_logs where candidate_id='TEST-C1'),'transfer adds no copied stages');
select pg_temp.assert_true((select l.entry_assignment_id=o.entry_assignment_id and l.stage_instance_id=o.stage_instance_id from public.recruitment_logs l join original_stage o on o.log_id=l.log_id),'transfer preserves entry attribution and stage identity');
select public.app_complete_pipeline_stage_v2(jsonb_build_object('candidate_id','TEST-C1','application_id',(select application_id from original_stage),'stage_instance_id',(select stage_instance_id from original_stage),'expected_updated_at',(select updated_at from public.recruitment_logs where candidate_id='TEST-C1'),'pending',jsonb_build_object('opened_date','2026-10-10'),'outcome',jsonb_build_object('result','pass','date','2026-10-11'),'next_pending',jsonb_build_object('stage','HR Interview','round',1)));
select pg_temp.assert_true((select entry_assignment_id<>outcome_assignment_id from public.recruitment_logs where candidate_id='TEST-C1' and recruitment_process='Phone Screen'),'outcome belongs to destination while entry belongs to source');
select pg_temp.assert_true((select count(*)=2 from public.recruitment_logs where candidate_id='TEST-C1'),'continuation creates only next pending stage');
select pg_temp.expect_error(format('select public.app_transfer_candidate_application_v1(%L::jsonb)',jsonb_build_object('candidate_id','TEST-C1','application_id',(select application_id from original_stage),'group_id','TEST-G1','expected_version',1,'reason','stale')),'APPLICATION_STALE_WRITE');
select public.app_upsert_candidate_reference_v1(jsonb_build_object('candidate_id',(select id from test_results where kind='pool'),'reference_name','Reference','relationship','Manager','channel_type','phone','channel_value','0811111111'));
select public.app_save_candidate_reference_check_v1(jsonb_build_object('candidate_id',(select id from test_results where kind='pool'),'application_id',(select application_id from test_results where kind='app1'),'reference_id',(select reference_id from public.candidate_references where candidate_id=(select id from test_results where kind='pool')),'checked_date','2026-10-11','duration_minutes',10,'conversation_summary','Good'));
select set_config('app.application_id',(select application_id::text from test_results where kind='app2'),true);
select pg_temp.expect_error(format('select app_private.assert_reference_check_passable(%L)',(select id from test_results where kind='pool')),'PIPELINE_REFERENCE_CHECKS_REQUIRED');
insert into auth.users(id,email,raw_user_meta_data) values('22222222-2222-2222-2222-222222222222','site@example.test','{"nickname":"Site"}'),('33333333-3333-3333-3333-333333333333','other@example.test','{"nickname":"Other"}');
update public.profiles set role='site_recruiter',site=case when id='22222222-2222-2222-2222-222222222222' then 'TEST' else 'OTHER' end where id in ('22222222-2222-2222-2222-222222222222','33333333-3333-3333-3333-333333333333');
select set_config('request.jwt.claim.sub','33333333-3333-3333-3333-333333333333',true);
select pg_temp.assert_true(not app_private.can_read_candidate((select id from test_results where kind='pool')),'other site cannot read profile');
select pg_temp.assert_true(not app_private.can_read_application((select application_id from test_results where kind='app1')),'other site cannot read independent journey');
select set_config('request.jwt.claim.sub','22222222-2222-2222-2222-222222222222',true);
select pg_temp.assert_true(app_private.can_read_candidate((select id from test_results where kind='pool')),'home site can read profile');
grant select on test_results,original_stage to authenticated;
set local role authenticated;
select pg_temp.assert_true((select count(*)=1 from public.candidates where candidate_id=(select id from test_results where kind='pool')),'home site RLS grants profile');
reset role;
select set_config('request.jwt.claim.sub','33333333-3333-3333-3333-333333333333',true);
set local role authenticated;
select pg_temp.assert_true(not exists(select 1 from public.candidates where candidate_id=(select id from test_results where kind='pool')),'cross-site RLS hides profile');
select pg_temp.assert_true(not exists(select 1 from public.recruitment_logs where application_id=(select application_id from test_results where kind='app1')),'cross-site RLS hides stages');
reset role;
select set_config('request.jwt.claim.sub','11111111-1111-1111-1111-111111111111',true);
select set_config('app.application_id','',true);
select public.app_transfer_candidate_application_v1(jsonb_build_object('candidate_id','TEST-C1','application_id',(select application_id from original_stage),'group_id','TEST-G1','expected_version',2,'reason','Return after HR begins'));
select public.app_transfer_candidate_application_v1(jsonb_build_object('candidate_id','TEST-C1','application_id',(select application_id from original_stage),'group_id','TEST-G2','expected_version',3,'reason','Repeated transfer'));
select pg_temp.assert_true((select count(*)=4 from public.candidate_application_assignments where application_id=(select application_id from original_stage)),'repeated transfers retain ordered intervals');
select pg_temp.assert_true((select count(*)=1 from public.recruitment_logs where application_id=(select application_id from original_stage) and recruitment_process='HR Interview' and result is null),'HR pending preserved without duplicate pass');
-- A new cross-site journey reveals the shared profile, never the independent home-site journey.
insert into public.requisitions(doc_id,site,position,department,head_count,status) values('TEST-R3','OTHER','Other position','Test',3,'ongoing');
insert into public.position_groups(group_id,group_position) values('TEST-G3','Other position');
insert into public.document_groups(doc_group_id,doc_id,group_id,group_position) values('TEST-D3','TEST-R3','TEST-G3','Other position');
select public.app_transfer_candidate_application_v1(jsonb_build_object('candidate_id',(select id from test_results where kind='pool'),'application_id',(select application_id from test_results where kind='app2'),'group_id','TEST-G3','expected_version',1,'reason','Admin cross-site assignment'));
select set_config('request.jwt.claim.sub','33333333-3333-3333-3333-333333333333',true);
set local role authenticated;
select pg_temp.assert_true(exists(select 1 from public.candidates where candidate_id=(select id from test_results where kind='pool')),'destination sees necessary profile');
select pg_temp.assert_true((select count(*)=2 from public.candidate_application_assignments where application_id=(select application_id from test_results where kind='app2')),'destination sees complete transferred history');
select pg_temp.assert_true(not exists(select 1 from public.candidate_applications where application_id=(select application_id from test_results where kind='app1')),'destination cannot see independent journey');
select pg_temp.expect_error(format('select public.app_transfer_candidate_application_v1(%L::jsonb)',jsonb_build_object('candidate_id',(select id from test_results where kind='pool'),'application_id',(select application_id from test_results where kind='app2'),'group_id','TEST-G2','expected_version',2,'reason','Unauthorized cross-site')),'APPLICATION_GROUP_NOT_AVAILABLE');
reset role;
select set_config('request.jwt.claim.sub','11111111-1111-1111-1111-111111111111',true);
select set_config('app.application_id',(select application_id::text from original_stage),true);
select public.app_correct_pipeline_outcome_v2(jsonb_build_object('candidate_id','TEST-C1','application_id',(select application_id from original_stage),'stage_instance_id',(select stage_instance_id from original_stage),'expected_updated_at',(select updated_at from public.recruitment_logs where stage_instance_id=(select stage_instance_id from original_stage)),'outcome',jsonb_build_object('result','pass','date','2026-10-11','remark','Corrected outcome detail')));
select pg_temp.assert_true((select entry_assignment_id=(select entry_assignment_id from original_stage) from public.recruitment_logs where candidate_id='TEST-C1' and recruitment_process='Phone Screen' and superseded_at is null),'correction preserves original entry assignment after transfer');
insert into public.interview_meetings(candidate_id,stage_instance_id,stage,starts_at,ends_at,interviewer_emails,status) select 'TEST-C1',stage_instance_id,'HR Interview',now()+interval '1 day',now()+interval '1 day 1 hour',array['qa@example.test'],'scheduled' from public.recruitment_logs where candidate_id='TEST-C1' and recruitment_process='HR Interview';
select pg_temp.expect_error(format('select public.app_transfer_candidate_application_v1(%L::jsonb)',jsonb_build_object('candidate_id','TEST-C1','application_id',(select application_id from original_stage),'group_id','TEST-G1','expected_version',4,'reason','Blocked meeting')),'APPLICATION_MEETING_REQUIRES_RESOLUTION');
update public.interview_meetings set status='cancelled' where candidate_id='TEST-C1';
-- Transfer after a completed HR Interview continues at the same Line Interview instance.
select public.app_complete_pipeline_stage_v2(jsonb_build_object('candidate_id','TEST-C1','application_id',(select application_id from original_stage),'stage_instance_id',(select stage_instance_id from public.recruitment_logs where candidate_id='TEST-C1' and recruitment_process='HR Interview' and superseded_at is null),'expected_updated_at',(select updated_at from public.recruitment_logs where candidate_id='TEST-C1' and recruitment_process='HR Interview' and superseded_at is null),'pending',jsonb_build_object('opened_date',(select log_date from public.recruitment_logs where candidate_id='TEST-C1' and recruitment_process='HR Interview' and superseded_at is null)),'outcome',jsonb_build_object('result','pass','date','2026-10-11'),'next_pending',jsonb_build_object('stage','Line Interview','round',1)));
create temp table before_hr_transfer as select stage_instance_id,entry_assignment_id from public.recruitment_logs where candidate_id='TEST-C1' and recruitment_process='Line Interview';
select public.app_transfer_candidate_application_v1(jsonb_build_object('candidate_id','TEST-C1','application_id',(select application_id from original_stage),'group_id','TEST-G1','expected_version',4,'reason','Fit after completed HR interview'));
select pg_temp.assert_true((select count(*)=1 from public.recruitment_logs where candidate_id='TEST-C1' and recruitment_process='HR Interview' and result=1 and superseded_at is null),'transfer after HR creates no duplicate pass');
select pg_temp.assert_true((select l.stage_instance_id=b.stage_instance_id and l.entry_assignment_id=b.entry_assignment_id and l.result is null from public.recruitment_logs l join before_hr_transfer b using(stage_instance_id)),'transfer after HR preserves pending Line stage');
-- Representative completed Offer fixtures exercise acceptance and no-show RPCs.
select set_config('app.application_id',(select application_id::text from test_results where kind='app1'),true);
update public.recruitment_logs set outcome_recorded_at=now(),result=1,outcome_date='2026-10-11' where application_id=(select application_id from test_results where kind='app1') and recruitment_process='Phone Screen';
insert into public.recruitment_logs(candidate_id,application_id,log_date,recruitment_process,round,result,outcome_date,outcome_recorded_at) select id,application_id,'2026-10-11','Offer',1,1,'2026-10-11',now() from test_results where kind='app1';
select public.app_upsert_offer(jsonb_build_object('mode','new','candidate_id',(select id from test_results where kind='pool'),'application_id',(select application_id from test_results where kind='app1'),'doc_id','TEST-R1','accepted_date','2026-10-11','first_working_date','2026-10-11'));
select pg_temp.expect_error(format('select public.app_transfer_candidate_application_v1(%L::jsonb)',jsonb_build_object('candidate_id',(select id from test_results where kind='pool'),'application_id',(select application_id from test_results where kind='app2'),'group_id','TEST-G2','expected_version',2,'reason','Accepted person blocked')),'APPLICATION_ACCEPTED_OFFER_BLOCKS_TRANSFER');
select set_config('app.application_id',(select application_id::text from test_results where kind='app2'),true);
update public.recruitment_logs set outcome_recorded_at=now(),result=1,outcome_date='2026-10-11' where application_id=(select application_id from test_results where kind='app2') and recruitment_process='Phone Screen';
insert into public.recruitment_logs(candidate_id,application_id,log_date,recruitment_process,round,result,outcome_date,outcome_recorded_at) select id,application_id,'2026-10-11','Offer',1,1,'2026-10-11',now() from test_results where kind='app2';
select pg_temp.expect_error(format('select public.app_upsert_offer(%L::jsonb)',jsonb_build_object('mode','new','candidate_id',(select id from test_results where kind='pool'),'application_id',(select application_id from test_results where kind='app2'),'doc_id','TEST-R3','accepted_date','2026-10-11','first_working_date','2026-10-11')),'offers_one_current_acceptance');
select set_config('app.application_id','',true);
select public.app_create_candidate_application_v1(jsonb_build_object('candidate_id',(select id from test_results where kind='pool'),'group_id','TEST-G1'));
select pg_temp.assert_true((select count(*)=2 from public.candidate_applications where candidate_id=(select id from test_results where kind='pool') and group_id='TEST-G1'),'fresh reapplication retains accepted history');
select public.app_confirm_offer_start_v1(jsonb_build_object('offer_id',(select offer_id from public.offers where application_id=(select application_id from test_results where kind='app1')),'expected_updated_at',(select updated_at from public.offers where application_id=(select application_id from test_results where kind='app1')),'start_confirmation','did_not_start','reason','Candidate did not attend'));
select pg_temp.assert_true((select state='closed' and closure_reason='did_not_start' from public.candidate_applications where application_id=(select application_id from test_results where kind='app1')),'no-show leaves older application historical when reapplication exists');
select pg_temp.assert_true((select count(*)=1 from public.candidate_applications where candidate_id=(select id from test_results where kind='pool') and group_id='TEST-G1' and state='active'),'no-show keeps one active reapplication');
select pg_temp.assert_true((select status='ongoing' from public.requisitions where doc_id='TEST-R1'),'no-show reopens demand');
select set_config('app.application_id','',true);
select pg_temp.expect_error('select public.app_upsert_candidate_profile_v1(''{"name":"Duplicate visible person","home_site":"TEST","phone_no":"0812345678"}''::jsonb)','PROFILE_DUPLICATE_ACKNOWLEDGEMENT_REQUIRED');
update public.requisitions set person_in_charge='Site' where doc_id='TEST-R3';
select set_config('request.jwt.claim.sub','22222222-2222-2222-2222-222222222222',true);
select pg_temp.expect_error(format('select public.app_create_candidate_application_v1(%L::jsonb)',jsonb_build_object('candidate_id','TEST-C1','group_id','TEST-G3')),'APPLICATION_CROSS_SITE_ADMIN_REQUIRED');
select set_config('request.jwt.claim.sub','33333333-3333-3333-3333-333333333333',true);
select public.app_upsert_candidate_profile_v1('{"name":"Separate inaccessible match","home_site":"OTHER","phone_no":"0812345678"}');
select pg_temp.assert_true(exists(select 1 from public.candidates where name='Separate inaccessible match' and home_site='OTHER'),'duplicate detection does not reveal inaccessible profiles');
reset role;
update public.profiles set role='viewer' where id='33333333-3333-3333-3333-333333333333';
select pg_temp.expect_error('select public.app_upsert_candidate_profile_v1(''{"name":"Viewer cannot write","home_site":"OTHER"}''::jsonb)','Recruitment write');
rollback;
